"""Halo final atlas, audited against the working main branch on 2026-10-24."""
from pathlib import Path
import ast,json,html
OUT=Path(__file__).resolve().parent
src=ast.parse((OUT.parent/'artbook-2026-10/build.py').read_text())
ICONS=next(ast.literal_eval(n.value) for n in src.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='paths' for t in n.targets))
ICONS.update({'close':'M5 5l14 14 M19 5L5 19','down':'M5 9l7 7 7-7','copy':'M8 8h13v13H8z M16 8V3H3v13h5','calendar':'M4 5h16v16H4z M4 10h16 M8 2v6 M16 2v6','smile':'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20 M8 9h.1 M16 9h.1 M7 14q5 6 10 0','refresh':'M20 8a9 9 0 1 0 1 8 M20 3v6h-6','expand':'M8 3H3v5 M16 3h5v5 M3 16v5h5 M21 16v5h-5','edit':'M4 16L16 4l4 4L8 20H4z','reply':'M9 5l-6 6 6 6 M3 11h9q8 0 8 9','download':'M12 3v12 M6 9l6 6 6-6 M3 18v3h18v-3','eye':'M2 12q10-14 20 0-10 14-20 0z M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8','pause':'M8 4v16 M16 4v16','monitor':'M2 3h20v14H2z M12 17v4 M7 21h10'})
def ic(n):return f'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="{ICONS[n]}"/></svg>'
def button(label,target=None,kind='',icon=None):
 return f'<button class="action {kind}" '+(f'data-go="{target}"' if target else 'data-demo="true"')+f'>{ic(icon) if icon else ""}<span>{label}</span></button>'
def ib(icon,label,target=None,kind=''):return f'<button class="ib {kind}" aria-label="{label}" title="{label}" '+(f'data-go="{target}"' if target else 'data-demo="true"')+f'>{ic(icon)}</button>'
def avatar(s,large=False):return f'<span class="avatar {"large" if large else ""}">{s}</span>'
def note(s,kind=''):return f'<p class="note {kind}">{s}</p>'
def field(label,value='',secret=False,help=''):
 return f'<label class="field"><span>{label}</span><input readonly value="{html.escape(value,quote=True)}" type="{"password" if secret else "text"}">{f"<small>{help}</small>" if help else ""}</label>'
def row(title,sub='',icon='arrow',target=None,trailing=None):return f'<div class="row">{ic(icon)}<div><b>{title}</b>{f"<small>{sub}</small>" if sub else ""}</div>{trailing if trailing is not None else ib("arrow","Открыть: "+title,target)}</div>'
def card(s):return f'<div class="card">{s}</div>'
def tabs(a,b,second=False):return f'<div class="tabs"><span class="{ "" if second else "selected"}">{a}</span><span class="{"selected" if second else ""}">{b}</span></div>'
def title(s,sub=''):return f'<h3>{s}</h3>'+ (note(sub) if sub else '')
def wave():return '<span class="wave" aria-hidden="true">'+''.join(f'<i style="height:{h}px"></i>' for h in [8,15,25,16,30,20,10,19,32,24,12,8,22,28,17,10,25,30,17,7,14,23,16,8])+'</span>'
def msg(text,own=False,time='14:30',name='',extra='',cls=''):
 sender='Вы · Антон' if own else (name or 'Мама')
 return f'<div class="message {"own" if own else "other"} {cls}"><div class="bubble"><b class="sender">{sender}</b><div class="messagecopy">{text}</div>{extra}<div class="msgmeta"><span>{time}{" · ✓✓" if own else ""}</span><button class="msgmore" aria-label="Действия с сообщением" data-go="{"message-menu-own" if own else "message-menu-other"}">⋯</button></div></div></div>'
def voicemsg(own=False,name=''):
 return msg(f'<div class="audio">{ib("play","Прослушать голосовое","voice-playing")}{wave()}<span>0:18</span></div>',own,'14:32',name,cls='voicemessage')
def photo(label='Фото',cls=''):
 return f'<div class="mediaart {cls}" role="img" aria-label="Иллюстративное вложение: {label}"><div class="hill h1"></div><div class="hill h2"></div><div class="sun"></div><span>{label}</span></div>'
def composer(text='',context='',draft='',mode='normal'):
 if mode=='record':return '<footer class="composer">'+f'<div class="recordline"><span class="recorddot"></span><b>Запись 0:12</b><small>осталось 2:48</small>{ib("trash","Удалить запись","chat")}{ib("stop","Остановить запись","voice-preview","primary")}</div><div class="recordwave">{wave()}</div></footer>'
 return '<footer class="composer">'+context+draft+f'<div class="count">{len(text)} / 16 000</div><div class="composerrow">{ib("plus","Дополнительные действия","composer-tools")}<div class="inputmock">{html.escape(text) if text else "Сообщение…"}</div>{ib("mic","Записать голосовое","voice-record")}{ib("send","Отправить" if mode!="scheduled" else "Запланировать","chat","primary")}</div></footer>'
def replybar(label='Ответ · Мама',text='В воскресенье собираемся у нас?'):return f'<div class="replybar"><div><b>{label}</b><small>{text}</small></div>{ib("close","Отменить","chat")}</div>'
def chathead(group=False):return f'<div class="chathead">{ib("back","Назад","groups" if group else "people")}<button class="identity" data-go="{"members" if group else "profile-contact"}">{avatar("С" if group else "М")}<span><b>{"Семья" if group else "Мама"}</b><small class="{'groupstatus' if group else 'online'}">{"4 участника" if group else "● В сети"}</small></span></button>{ib("more","Меню чата","chat-menu")}{ib("phone","Голосовой звонок","call-active")}{ib("video","Видеозвонок","video-call")}</div>'
def timeline(group=False):
 return '<div class="day">Сегодня, 24 октября</div>'+msg('В воскресенье собираемся у нас?',name='Мама')+msg('Да, буду к пяти.',True,'14:31')+voicemsg(name='Мама')+msg('Я привезу десерт.',time='14:33',name='Аня' if group else 'Мама')+msg('Отлично! Что-нибудь купить?',True,'14:33')+msg('Только чай, остальное есть.',time='14:34')+msg('Договорились.',True,'14:34')+msg('Папа тоже будет к пяти.',time='14:35')+msg('Уже написал ему.',True,'14:35')+msg('До встречи!',time='14:36')
def scheduledbar():
 return '<button class="scheduledbar" data-go="scheduled-list">'+ic('clock')+'<span><b>Запланированные сообщения <em>2</em></b><small>Ближайшее: сегодня в 17:00</small></span>'+ic('arrow')+'</button>'
def chatbody(content=None,group=False,footer=None,banner='',search=False):
 return chathead(group)+banner+(f'<div class="searchbar">{ic("search")}<span>Поиск в переписке</span>{ib("calendar","Перейти к дате","history-calendar")}</div>' if search else '')+scheduledbar()+'<div class="body timeline">'+(timeline(group) if content is None else content)+'</div>'+(composer() if footer is None else footer)
def keyboard():return '<div class="keyboard" aria-label="Схематичная клавиатура, не системный снимок"><div class="suggestions">Да <span>Хорошо</span> Сегодня</div>'+''.join('<div class="keyrow">'+''.join(f'<span>{c}</span>' for c in line)+'</div>' for line in ['йцукенгшщзх','фывапролджэ','↑ячсмитьбю⌫'])+'<div class="keyrow"><span>123</span><span class="spacekey">Русский</span><span>↵</span></div></div>'
def body(s):return f'<div class="body">{s}</div>'
def footer(*buttons):return '<footer class="footer">'+''.join(buttons)+'</footer>'
def phonecontent(s,foot=''):return body(s)+foot
SCREENS=[]
def add(key,label,group,content,source,functions,layout='',platform='both',custom=False):
 SCREENS.append(dict(key=key,label=label,group=group,content=content,source=source,functions=functions,layout=layout,platform=platform,custom=custom))
